// ---------------------------------------------------------------------------

const objectSchema = z.object({ foo: z.string(), count: z.number() });

expectTypeOf<GenerateObjectInput<{ foo: string; count: number }>>().toEqualTypeOf<{
  schema: z.ZodSchema<{ foo: string; count: number }>;
  prompt: string;
  model?: string;
  temperature?: number;
  maxTokens?: number;
}>();

